<?php
require_once __DIR__.'/../includes/functions.php';need_role(['petugas']);$q=trim($_GET['q']??'');$st=$_GET['status']??'';$cat=(int)($_GET['kategori']??0);$from=$_GET['dari']??'';$to=$_GET['sampai']??'';$where=['r.id_petugas=?'];$args=[me()['id_user']];if($q!==''){$where[]='(r.nomor_laporan LIKE ? OR r.judul LIKE ?)';array_push($args,'%'.$q.'%','%'.$q.'%');}if(in_array($st,status_options(),true)){$where[]='r.status=?';$args[]=$st;}if($cat>0){$where[]='r.id_kategori=?';$args[]=$cat;}if($from!==''&&valid_date_format($from)){$where[]='DATE(r.created_at)>=?';$args[]=$from;}if($to!==''&&valid_date_format($to)){$where[]='DATE(r.created_at)<=?';$args[]=$to;}$base=' FROM reports r JOIN categories c ON c.id_kategori=r.id_kategori WHERE '.implode(' AND ',$where);$cnt=db()->prepare('SELECT COUNT(*)'.$base);$cnt->execute($args);$pg=paginate((int)$cnt->fetchColumn());$s=db()->prepare('SELECT r.id_laporan,r.nomor_laporan,r.judul,r.status,r.created_at,c.nama_kategori'.$base.' ORDER BY r.created_at DESC LIMIT '.$pg['per_page'].' OFFSET '.$pg['offset']);$s->execute($args);$rows=$s->fetchAll();$cats=db()->query('SELECT id_kategori,nama_kategori FROM categories WHERE status_kategori=1 ORDER BY nama_kategori')->fetchAll();header_page('Laporan Ditugaskan');?><h1>Laporan yang ditugaskan</h1><form class="search" method="get"><input name="q" placeholder="Nomor atau judul" value="<?=e($q)?>"><select name="status"><option value="">Semua status</option><?php foreach(status_options() as $o):?><option <?=($st===$o?'selected':'')?> value="<?=e($o)?>"><?=e($o)?></option><?php endforeach;?></select><select name="kategori"><option value="0">Semua kategori</option><?php foreach($cats as $c):?><option value="<?=$c['id_kategori']?>" <?=($cat===(int)$c['id_kategori']?'selected':'')?>><?=e($c['nama_kategori'])?></option><?php endforeach;?></select><label>Dari<input type="date" name="dari" value="<?=e($from)?>"></label><label>Sampai<input type="date" name="sampai" value="<?=e($to)?>"></label><button class="btn">Filter</button></form><div class="table-wrap"><table><tr><th>Nomor</th><th>Judul</th><th>Kategori</th><th>Status</th><th>Tanggal</th><th>Aksi</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nomor_laporan'])?></td><td><?=e($r['judul'])?></td><td><?=e($r['nama_kategori'])?></td><td><?=status_badge($r['status'])?></td><td><?=e($r['created_at'])?></td><td><a href="detail_laporan.php?id=<?=$r['id_laporan']?>">Buka</a></td></tr><?php endforeach;?></table></div><?php if(!$rows):?><div class="empty">Tidak ada laporan yang cocok.</div><?php endif;?><?php pagination_links($pg);?><?php footer_page();?>